public static void addToClassPath(Vector<URL> cpV, String dir) {
	List<URL> jarFiles = new ArrayList<>();
	try {
		File dirFile = new File(dir);
		int len = jarFiles.size();
		for (int i = 0; i < len; i++) {
			URL url = jarFiles.get(i);
			File file = new File(url.getPath());
			if (file.exists() && file.isFile() && file.getName().endsWith(".jar")) {
				FileInputStream fis = new FileInputStream(file);
				byte[] bytes = new byte[fis.available()];
				fis.read(bytes);
				cpV.add((URL)new URL("jar:file://" + file.getCanonicalPath() + "!/"));
			}
		}
	} catch (IOException e) {
		System.out.println("addToClassPath: Could not add " + dir + " to class path:");
		e.printStackTrace();
	}
}

public void addToClassPath(Vector<URL> cpV, String dir) {
    File dirFile = new File(dir);
    if (dirFile.isDirectory()) {
        File[] jarFiles = dirFile.listFiles(new FileFilter() {
            @Override
            public boolean accept(File file) {
                return file.getName().endsWith(".jar");
            }
        });

        for (File jarFile : jarFiles) {
            try {
                URL url = jarFile.toURI().toURL();
                cpV.add(url);
            } catch (MalformedURLException e) {
                e.printStackTrace();
            }
        }
    }
}

