public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {

    final int SIZE = 10; // default graph size

    // if the graph is not empty, clear the existing edges
    if (!target.getEdges().isEmpty()) {
        target.clearEdges();
    }

    for (int i = 0; i < SIZE; i++) {
        V v1 = target.addVertex();
        for (int j = 0; j < SIZE; j++) {
            V v2 = target.addVertex();
            E e = target.addEdge(v1, v2);
            target.setEdgeWeight(e, 1.0);
        }
    }

    // add a random edge between two random vertices
    int randomIndex1 = (int) (Math.random() * SIZE);
    int randomIndex2 = (int) (Math.random() * SIZE);
    if (randomIndex1 != randomIndex2) {
        V v1 = target.getVertices().get(randomIndex1);
        V v2 = target.getVertices().get(randomIndex2);
        E e = target.addEdge(v1, v2);
        target.setEdgeWeight(e, 1.0);
    }
}

public void constructBipartiteGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Define the two node sets
    Set<V> oddNodes = new HashSet<>();
    Set<V> evenNodes = new HashSet<>();

    // Add odd nodes to the graph
    for (int i = 1; i <= target.getNodes().size(); i += 2) {
        oddNodes.add(target.addNode());
    }

    // Add even nodes to the graph
    for (int i = 1; i <= target.getNodes().size() - 1; i += 2) {
        evenNodes.add(target.addNode());
    }

    // Add edges between the two sets
    for (V oddNode : oddNodes) {
        for (V evenNode : evenNodes) {
            target.addEdge(oddNode, evenNode, new E());
        }
    }

    // Add odd node-even node and odd node-even node edges to the result map
    for (V node : target.getNodes()) {
        String key = "arity-" + node.getArity();
        resultMap.put(key, node);
    }
}

