public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.get serializer(out.getClass()).serialize(message, out, buffer);
    int length = CodedOutputStream.computeSizeNoTag(size);
    Arrays.fill(buffer.data, 0, length + 13, (byte) 0);
    CodedOutputStream codedOut = CodedOutputStream.newInstance(buffer.data, 0, length + 13);
