/**
 * Performs variable substitution on the given input string using the provided properties.
 *
 * @param input The input string to perform substitution on
 * @param props The properties to use for substitution
 * @return The input string with all variables substituted
 */
public static String substitute(String input, Properties props) {
    StringBuffer sb = new StringBuffer();
    StringBuffer varNames = new StringBuffer();
    Matcher matcher = Pattern.compile("\\$\\{.*?\\}").matcher(input);
    while (matcher.find()) {
        String varName = matcher.group();
        if (varNames.length() > 0) {
            varNames.append(",");
        }
        varNames.append(varName);
        String varValue = props.getProperty(varName.substring(2, varName.length() - 1));
        matcher.appendReplacement(sb, varValue == null ? "" : varValue);
    }
    matcher.appendTail(sb);
    if (varNames.length() > 0) {
        logInfo("Variables \"" + varNames + "\" were substituted with values");
    }
    return sb.toString();
}

