/**
 * Reverses an array of objects.
 * 
 * @param array  the array to reverse, may be null
 * @param <T>  the component type of the array
 * @return  the reversed array, null if null array input
 * @since  3.2
 */
public static <T> T[] reverse(final T[] array) {
  if (array == null) {
    return null;
  }
  final int n = array.length;
  if (n == 0) {
    return array;
  }
  final T[] result = Arrays.copyOf(array, n);
  for (int i = 0; i < n >> 1; i++) {
    final T tmp = result[i];
    result[i] = result[n - i - 1];
    result[n - i - 1] = tmp;
  }
  return result;
}

