 * Generates the next permutation of an array
 *
 * @param array the input array
 * @return the next permutation of the array
 */
public static int[] nextPermutation(int[] array) {
    int i = array.length - 2;
    while (i >= 0 && array[i] >= array[i + 1]) {
        i--;
    }
    if (i == -1) {
        return null;
    }
    int j = array.length - 1;
    while (array[j] <= array[i]) {
        j--;
    }
    int temp = array[i];
    array[i] = array[j];
    array[j] = temp;
    j = array.length - 1;
    while (i < j) {
        temp = array[i];
        array[i] = array[j];
        array[j] = temp;
        i++;
        j--;
    }
    return array;
}

