public static String applyRelativePath(String path, String relativePath) {
String[] pathParts = path.split("/");
String[] relativePathParts = relativePath.split("/");

// Iterate through the parts of the relative path and apply them to the
// original path
for (String relativePathPart : relativePathParts) {
    if (relativePathPart.equals(".")) {
        // Do nothing, this is just a reference to the current directory
    } else if (relativePathPart.equals("..")) {
        // Remove the last part of the path
        pathParts = Arrays.copyOf(pathParts, pathParts.length - 1);
    } else {
        // Add the part to the end of the path
        String[] newPathParts = new String[pathParts.length + 1];
        System.arraycopy(pathParts, 0, newPathParts, 0, pathParts.length);
        newPathParts[pathParts.length] = relativePathPart;
        pathParts = newPathParts;
    }
}

// Join the path parts back together to form the full path
StringBuilder sb = new StringBuilder();
for (String pathPart : pathParts) {
    sb.append(pathPart);
    sb.append("/");
}

// Remove the last "/" character
return sb.substring(0, sb.length() - 1);
}

